//! Time-anchored randomness and NSF phase continuity (P3-C1, ADR 0004).
//!
//! - `z_noise` (flow prior noise, `N(0,1) × noise_scale`, RVC 0.66666) and `src_noise` (NSF source
//!   noise, `N(0,1)` per output sample) are generated by a counter-based generator keyed by
//!   `(seed, stream, absolute index)`: the frames two overlapping ticks share get identical noise,
//!   so SOLA seams disappear (competitors redraw noise every chunk). The absolute index comes from
//!   `ConversionCtx::stream_pos_16k`.
//! - `phase0` is the NSF sine phase at the window's first sample, carried in f64:
//!   `phase0' = frac(phase0 + Σ wrap(upp · f0 / sr))` over the frames that slide out.
//!
//! Legacy lever paths: `anchored_noise` off draws fresh noise per tick (seeded by the tick
//! counter); `nsf_phase0` off feeds phase 0 every tick.
//!
//! # Frozen by P3-S0 (signatures; P3-C1 implements)
//! - [`NoiseStream`], [`AnchoredNoise::new`], [`AnchoredNoise::fill`] (allocation-free, fills a
//!   caller buffer with `N(0,1) × scale` for indices `start .. start + out.len()`).
//! - [`PhaseTracker::new`], [`PhaseTracker::phase_at`], [`PhaseTracker::advance`],
//!   [`PhaseTracker::reset`].
//!
//! # Added by P3-C1
//! - [`FRAME_STRIDE`] (the flow noise index is `channel * FRAME_STRIDE + absolute frame`).
//! - [`NoiseFrames`]: a per-stream cache of unit noise keyed by absolute frame, so a tick
//!   generates only the frames it has not seen (a window of `F` frames slides by one block).
//! - [`excitation_increment`]: the per-frame phase increment exactly as the template graph
//!   computes it (fp32), shared by [`PhaseTracker`] and the tests' reference excitation.

/// Stride between the flow noise of two latent channels (absolute frames never reach it: 2^40
/// frames of 10 ms are 348 years).
pub const FRAME_STRIDE: u64 = 1 << 40;

/// Which noise sequence (independent streams of one seed).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum NoiseStream {
    /// Flow prior noise, indexed by `channel * FRAME_STRIDE + absolute frame`.
    Flow,
    /// NSF source noise, indexed by absolute output sample.
    Source,
}

impl NoiseStream {
    fn key(self) -> u64 {
        match self {
            NoiseStream::Flow => 0x243F_6A88_85A3_08D3,
            NoiseStream::Source => 0x1319_8A2E_0370_7344,
        }
    }
}

/// SplitMix64 finaliser: a bijective 64-bit mix with full avalanche.
#[inline]
fn mix64(mut z: u64) -> u64 {
    z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
    z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
    z ^ (z >> 31)
}

/// Counter-based Gaussian noise anchored to absolute time.
#[derive(Clone, Copy, Debug)]
pub struct AnchoredNoise {
    seed: u64,
}

impl AnchoredNoise {
    pub fn new(seed: u64) -> AnchoredNoise {
        AnchoredNoise {
            seed: mix64(seed ^ 0x9E37_79B9_7F4A_7C15),
        }
    }

    /// Unit Gaussian of `(stream, index)`: Box-Muller over two 32-bit uniforms of one hash, so
    /// every index is independent of every other (no pairing, any window can be filled alone).
    #[inline]
    pub fn unit(&self, stream: NoiseStream, index: u64) -> f32 {
        let h = mix64(mix64(self.seed ^ stream.key()) ^ index.wrapping_mul(0x9E37_79B9_7F4A_7C15));
        // u1 in (0, 1] (never 0, so the log is finite), u2 in [0, 1).
        let u1 = ((h >> 32) as f64 + 1.0) * (1.0 / 4_294_967_296.0);
        let u2 = (h & 0xFFFF_FFFF) as f64 * (1.0 / 4_294_967_296.0);
        ((-2.0 * u1.ln()).sqrt() * (std::f64::consts::TAU * u2).cos()) as f32
    }

    /// Fill `out` with `N(0,1) × scale` for indices `start..start + out.len()` of `stream`: the
    /// same `(stream, index)` always gives the same value.
    pub fn fill(&self, stream: NoiseStream, start: u64, scale: f32, out: &mut [f32]) {
        for (i, v) in out.iter_mut().enumerate() {
            *v = self.unit(stream, start.wrapping_add(i as u64)) * scale;
        }
    }
}

/// Unit noise of one stream cached per absolute frame (`width` values per frame), so a window of
/// frames that slides by a block only generates the new frames. Layout inside the cache is
/// frame-major (`[frame][width]`); [`copy_window`](Self::copy_window) writes either layout.
pub struct NoiseFrames {
    noise: AnchoredNoise,
    stream: NoiseStream,
    width: usize,
    /// Frames the ring holds.
    capacity: usize,
    ring: Vec<f32>,
    /// Absolute frames `[start, end)` currently valid in the ring.
    start: u64,
    end: u64,
}

impl NoiseFrames {
    /// A cache of `capacity` frames of `width` unit values (`capacity` must cover the largest
    /// window read at once).
    pub fn new(noise: AnchoredNoise, stream: NoiseStream, width: usize, capacity: usize) -> NoiseFrames {
        let capacity = capacity.max(1);
        NoiseFrames {
            noise,
            stream,
            width,
            capacity,
            ring: vec![0.0; capacity * width],
            start: 0,
            end: 0,
        }
    }

    pub fn width(&self) -> usize {
        self.width
    }

    /// Unit value `k` of absolute frame `frame` (the counter index this cache uses).
    fn index(&self, frame: u64, k: usize) -> u64 {
        match self.stream {
            // `channel * FRAME_STRIDE + frame` (the documented flow layout).
            NoiseStream::Flow => (k as u64).wrapping_mul(FRAME_STRIDE).wrapping_add(frame),
            // Absolute output sample.
            NoiseStream::Source => frame.wrapping_mul(self.width as u64).wrapping_add(k as u64),
        }
    }

    fn generate(&mut self, frame: u64) {
        let slot = (frame % self.capacity as u64) as usize * self.width;
        for k in 0..self.width {
            let idx = self.index(frame, k);
            self.ring[slot + k] = self.noise.unit(self.stream, idx);
        }
    }

    /// Make frames `[first, first + frames)` valid, generating only the ones not cached.
    fn ensure(&mut self, first: u64, frames: usize) {
        let last = first + frames as u64;
        let frames = frames.min(self.capacity);
        let first = last - frames as u64;
        if first >= self.end || last <= self.start || first < self.start {
            // Disjoint from (or before) the cached span: start over at this window.
            for f in first..last {
                self.generate(f);
            }
            self.start = first;
            self.end = last;
            return;
        }
        for f in self.end..last {
            self.generate(f);
        }
        self.end = self.end.max(last);
        self.start = self
            .start
            .max(self.end.saturating_sub(self.capacity as u64));
    }

    /// Copy frames `[first, first + frames)` scaled by `scale` into `out`: frame-major
    /// (`[frame][width]`, e.g. the NSF source samples of consecutive frames) or channel-major
    /// (`[width][frames]`, the `[1, C, F]` flow noise tensor).
    pub fn copy_window(&mut self, first: u64, frames: usize, scale: f32, channel_major: bool, out: &mut [f32]) {
        debug_assert!(frames <= self.capacity, "window of {frames} frames > cache of {}", self.capacity);
        debug_assert_eq!(out.len(), frames * self.width);
        self.ensure(first, frames);
        let w = self.width;
        for f in 0..frames {
            let slot = ((first + f as u64) % self.capacity as u64) as usize * w;
            let src = &self.ring[slot..slot + w];
            if channel_major {
                for (k, &v) in src.iter().enumerate() {
                    out[k * frames + f] = v * scale;
                }
            } else {
                for (o, &v) in out[f * w..(f + 1) * w].iter_mut().zip(src) {
                    *o = v * scale;
                }
            }
        }
    }

    /// Forget the cached frames (a new seed or a restart).
    pub fn clear(&mut self) {
        self.start = 0;
        self.end = 0;
    }
}

/// Phase advance (cycles) of the NSF sine over one frame of `upp` samples at `f0` Hz, computed
/// exactly like the template graph (`f0 / sr * upp` in fp32, ADR 0004) and wrapped to
/// `[-0.5, 0.5)`. Unvoiced (`<= 0`) and non-finite frames advance nothing, like the graph's
/// zero-F0 frames.
#[inline]
pub fn excitation_increment(f0: f32, upp: usize, sample_rate: u32) -> f64 {
    if !(f0.is_finite() && f0 > 0.0) {
        return 0.0;
    }
    let x = f64::from(f0 / sample_rate as f32 * upp as f32);
    x - (x + 0.5).floor()
}

/// NSF sine phase (cycles, in `[0, 1)`) at the first sample of the decode window.
#[derive(Clone, Copy, Debug, Default)]
pub struct PhaseTracker {
    phase: f64,
    upp: usize,
    sample_rate: u32,
}

impl PhaseTracker {
    pub fn new(upp: usize, sample_rate: u32) -> PhaseTracker {
        PhaseTracker {
            phase: 0.0,
            upp,
            sample_rate,
        }
    }

    /// Phase at the current window start.
    pub fn phase_at(&self) -> f64 {
        self.phase
    }

    /// Slide the window by the frames in `f0_out` (Hz per frame, unvoiced 0).
    pub fn advance(&mut self, f0_out: &[f32]) {
        let sum: f64 = f0_out
            .iter()
            .map(|&f| excitation_increment(f, self.upp, self.sample_rate))
            .sum();
        let p = self.phase + sum;
        self.phase = p - p.floor();
        if !self.phase.is_finite() || self.phase >= 1.0 {
            self.phase = 0.0;
        }
    }

    /// Start over at phase 0 (a stream gap or restart).
    pub fn reset(&mut self) {
        self.phase = 0.0;
    }
}

#[cfg(test)]
pub(crate) mod tests {
    use super::*;

    /// The template graph's NSF sine phase (cycles, unwrapped) of every sample of a window
    /// (`excitation()` in `scripts/vc-templates/rvc_arch/split.py`, in f64): sample `k` (1-based)
    /// of frame `f` is at `phase0 + Σ_{i<f} wrap(upp·f0_i/sr) + k·f0_f/sr`.
    pub(crate) fn reference_phase(f0: &[f32], phase0: f64, upp: usize, sr: u32) -> Vec<f64> {
        let mut out = Vec::with_capacity(f0.len() * upp);
        let mut acc = 0.0f64;
        for &f in f0 {
            let per = if f.is_finite() && f > 0.0 { f64::from(f / sr as f32) } else { 0.0 };
            for k in 1..=upp {
                out.push(phase0 + acc + per * k as f64);
            }
            acc += excitation_increment(f, upp, sr);
        }
        out
    }

    fn frac_dist(a: f64, b: f64) -> f64 {
        let d = (a - b).rem_euclid(1.0);
        d.min(1.0 - d)
    }

    #[test]
    fn noise_is_deterministic_per_index_and_gaussian() {
        let n = AnchoredNoise::new(42);
        let mut a = vec![0.0; 4096];
        let mut b = vec![0.0; 1000];
        n.fill(NoiseStream::Source, 10_000, 1.0, &mut a);
        // Any sub-window gives the same values at the same indices, at any scale.
        n.fill(NoiseStream::Source, 10_500, 0.5, &mut b);
        for (i, &v) in b.iter().enumerate() {
            assert_eq!(v, a[500 + i] * 0.5);
        }
        // Streams and seeds are independent.
        let mut c = vec![0.0; 4096];
        n.fill(NoiseStream::Flow, 10_000, 1.0, &mut c);
        assert_ne!(a, c);
        let mut d = vec![0.0; 4096];
        AnchoredNoise::new(43).fill(NoiseStream::Source, 10_000, 1.0, &mut d);
        assert_ne!(a, d);
        // Moments of N(0, 1) over 200k draws.
        let mut big = vec![0.0f32; 200_000];
        n.fill(NoiseStream::Flow, 0, 1.0, &mut big);
        let mean = big.iter().map(|&x| f64::from(x)).sum::<f64>() / big.len() as f64;
        let var = big
            .iter()
            .map(|&x| (f64::from(x) - mean).powi(2))
            .sum::<f64>()
            / big.len() as f64;
        let kurt = big
            .iter()
            .map(|&x| (f64::from(x) - mean).powi(4))
            .sum::<f64>()
            / big.len() as f64
            / (var * var);
        assert!(mean.abs() < 0.01, "mean {mean}");
        assert!((var - 1.0).abs() < 0.02, "variance {var}");
        assert!((kurt - 3.0).abs() < 0.1, "kurtosis {kurt}");
        assert!(big.iter().all(|x| x.is_finite()));
        // Neighbouring indices are uncorrelated.
        let lag1 = big
            .windows(2)
            .map(|w| f64::from(w[0]) * f64::from(w[1]))
            .sum::<f64>()
            / big.len() as f64;
        assert!(lag1.abs() < 0.01, "lag-1 correlation {lag1}");
    }

    /// Overlapping windows read from the frame cache are identical wherever they share frames, in
    /// both layouts, and equal direct `fill` calls with the documented index layout.
    #[test]
    fn noise_windows_are_identical_across_overlaps() {
        let noise = AnchoredNoise::new(7);
        let (c, f, block) = (6usize, 20usize, 4u64);
        let mut flow = NoiseFrames::new(noise, NoiseStream::Flow, c, f + 8);
        let mut src = NoiseFrames::new(noise, NoiseStream::Source, 8, f + 8);
        let mut prev: Option<(u64, Vec<f32>, Vec<f32>)> = None;
        for tick in 0..50u64 {
            let first = 1_000 + tick * block;
            let mut zw = vec![0.0; c * f];
            let mut sw = vec![0.0; 8 * f];
            flow.copy_window(first, f, 0.66666, true, &mut zw);
            src.copy_window(first, f, 1.0, false, &mut sw);
            // Direct fills with the documented indices.
            for ch in 0..c {
                let mut direct = vec![0.0; f];
                noise.fill(NoiseStream::Flow, ch as u64 * FRAME_STRIDE + first, 0.66666, &mut direct);
                assert_eq!(&zw[ch * f..(ch + 1) * f], &direct[..], "tick {tick} channel {ch}");
            }
            let mut direct = vec![0.0; 8 * f];
            noise.fill(NoiseStream::Source, first * 8, 1.0, &mut direct);
            assert_eq!(sw, direct, "tick {tick}");
            if let Some((p_first, pz, ps)) = &prev {
                let shift = (first - p_first) as usize;
                for ch in 0..c {
                    assert_eq!(&zw[ch * f..ch * f + f - shift], &pz[ch * f + shift..(ch + 1) * f]);
                }
                assert_eq!(&sw[..(f - shift) * 8], &ps[shift * 8..]);
            }
            prev = Some((first, zw, sw));
        }
        // A jump (gap) and a step back regenerate correctly.
        let mut a = vec![0.0; c * f];
        flow.copy_window(5_000, f, 1.0, true, &mut a);
        let mut b = vec![0.0; c * f];
        flow.copy_window(10, f, 1.0, true, &mut b);
        let mut fresh = NoiseFrames::new(noise, NoiseStream::Flow, c, f);
        let mut want = vec![0.0; c * f];
        fresh.copy_window(10, f, 1.0, true, &mut want);
        assert_eq!(b, want);
    }

    /// Consecutive decode windows sliding by a block see exactly the same excitation phase on every
    /// sample they share, on an F0 ramp with unvoiced gaps (no phase jump at any tick), and the
    /// sine is continuous from one window's first sample to the frame before it.
    #[test]
    fn phase_is_continuous_across_ticks_on_an_f0_ramp() {
        for &(upp, sr) in &[(400usize, 40_000u32), (480, 48_000), (320, 32_000), (8, 16_000)] {
            let total = 600usize;
            // 80 -> 900 Hz ramp with vibrato and two unvoiced gaps.
            let f0: Vec<f32> = (0..total)
                .map(|i| {
                    if (200..212).contains(&i) || (401..405).contains(&i) {
                        0.0
                    } else {
                        let t = i as f32 / total as f32;
                        80.0 + 820.0 * t + 15.0 * (i as f32 * 0.3).sin()
                    }
                })
                .collect();
            let (window, block) = (46usize, 4usize);
            let mut tracker = PhaseTracker::new(upp, sr);
            let mut prev: Option<(usize, Vec<f64>)> = None;
            let mut start = 0usize;
            while start + window <= total {
                let phases = reference_phase(&f0[start..start + window], tracker.phase_at(), upp, sr);
                if let Some((p_start, p_phases)) = &prev {
                    let shift = (start - p_start) * upp;
                    for (i, &p) in phases[..phases.len() - shift].iter().enumerate() {
                        let d = frac_dist(p, p_phases[i + shift]);
                        assert!(d < 1e-9, "upp {upp}: window {start} sample {i}: phase jump of {d} cycles");
                    }
                }
                prev = Some((start, phases));
                tracker.advance(&f0[start..start + block]);
                assert!((0.0..1.0).contains(&tracker.phase_at()));
                start += block;
            }
            // The window-start phase is the whole stream's accumulated excitation phase there: the
            // same value a single decode from the stream start would use at that frame.
            let expected: f64 = f0[..start]
                .iter()
                .map(|&f| excitation_increment(f, upp, sr))
                .sum();
            assert!(
                frac_dist(expected, tracker.phase_at()) < 1e-9,
                "upp {upp}: {expected} vs {}",
                tracker.phase_at()
            );
            // The last window decoded with the tracked phase0 equals the same span of one decode
            // from the stream's start.
            let last_start = start - block;
            let whole = reference_phase(&f0[..last_start + window], 0.0, upp, sr);
            let mut t = PhaseTracker::new(upp, sr);
            t.advance(&f0[..last_start]);
            let last = reference_phase(&f0[last_start..last_start + window], t.phase_at(), upp, sr);
            for (i, &p) in last.iter().enumerate() {
                let d = frac_dist(p, whole[last_start * upp + i]);
                assert!(d < 1e-6, "upp {upp}: sample {i} differs from a whole-stream decode by {d}");
            }
        }
    }

    #[test]
    fn increments_follow_the_graph_and_skip_unvoiced_frames() {
        assert_eq!(excitation_increment(0.0, 400, 40_000), 0.0);
        assert_eq!(excitation_increment(f32::NAN, 400, 40_000), 0.0);
        assert_eq!(excitation_increment(-5.0, 400, 40_000), 0.0);
        // 100 Hz over 10 ms = exactly one cycle -> 0.
        assert!(excitation_increment(100.0, 400, 40_000).abs() < 1e-6);
        // 150 Hz over 10 ms = 1.5 cycles -> wrapped to -0.5.
        assert!((excitation_increment(150.0, 400, 40_000) + 0.5).abs() < 1e-6);
        let v = excitation_increment(237.3, 480, 48_000);
        assert!((-0.5..0.5).contains(&v));
        let mut t = PhaseTracker::new(400, 40_000);
        t.advance(&[125.0, 125.0]);
        assert!((t.phase_at() - 0.5).abs() < 1e-6, "{}", t.phase_at());
        t.reset();
        assert_eq!(t.phase_at(), 0.0);
    }
}
